function sw(k){return swWords[k]?.[['az','tr','ru','en','ar'].indexOf(lang())]||swWords[k]?.[0]||k}
const SHAMS_PUBLIC_URL='https://mubaristi-create.github.io/basira/';
function azanCard(){return `<section class="card azan-card" data-localized="true"><div class="azan-line"><span class="azan-wave" aria-hidden="true"><i></i><i></i><i></i></span><div><h3>${sw('azan')}</h3><p class="muted">${sw('audioNote')}</p></div></div><button id="azanButton" class="goldbtn wide" aria-pressed="false" onclick="toggleAzan()">▶ ${sw('azan')}</button><audio id="azanAudio" controls preload="none" aria-label="${sw('azan')}" onplay="updateAzanButton(true)" onpause="updateAzanButton(false)" onended="updateAzanButton(false)" onerror="azanAudioError()"><source src="audio/adhan.mp3" type="audio/mpeg"><source src="audio/adhan.ogg" type="audio/ogg"></audio><small id="azanStatus" role="status"></small><details><summary>${sw('source')}</summary><p>Andrewler · <a href="https://commons.wikimedia.org/wiki/File:Azan.ogg" target="_blank" rel="noopener">Azan.ogg</a> · <a href="https://creativecommons.org/licenses/by-sa/4.0/" target="_blank" rel="noopener">CC BY-SA 4.0</a>. Original recording unchanged; MP3 transcode by Wikimedia.</p></details></section>`}
async function toggleAzan(){const audio=document.querySelector('#azanAudio');if(!audio)return;try{if(!audio.paused){audio.pause();return}document.querySelectorAll('audio').forEach(a=>{if(a!==audio)a.pause()});await audio.play()}catch{azanAudioError()}}
function updateAzanButton(playing){const b=document.querySelector('#azanButton');if(b){b.textContent=(playing?'Ⅱ ':'▶ ')+sw(playing?'pause':'azan');b.setAttribute('aria-pressed',String(playing))}document.querySelector('.azan-card')?.classList.toggle('is-playing',playing)}
function azanAudioError(){const s=document.querySelector('#azanStatus');if(s)s.textContent=sw('audioError');updateAzanButton(false)}
function specialPrayerLink(){return `<button class="card special-link" onclick="go('special')" data-localized="true"><span>☾</span><strong>${sw('special')}</strong><span>›</span></button>`}
async function shareApp(){const data={title:'SHAMS',text:sw('shareText'),url:SHAMS_PUBLIC_URL};if(window.ShamsAndroid?.shareApp){window.ShamsAndroid.shareApp(data.text,SHAMS_PUBLIC_URL);return}if(navigator.share){try{await navigator.share(data);return}catch(e){if(e?.name==='AbortError')return}}go('share')}
async function copyAppLink(){try{if(!navigator.clipboard?.writeText)throw Error();await navigator.clipboard.writeText(SHAMS_PUBLIC_URL);toast(sw('copied'))}catch{const input=document.querySelector('#shareLink');input?.focus();input?.select();toast(sw('copyHint'))}}
function sharePage(){const message=encodeURIComponent(sw('shareText')+' '+SHAMS_PUBLIC_URL);return `<div data-localized="true">${head(sw('share'),'')}<section class="card share-panel"><span class="share-orbit">↗</span><h2>SHAMS</h2><p>${sw('shareText')}</p><button class="goldbtn wide" onclick="shareApp()">↗ ${sw('share')}</button><div class="share-networks"><a class="secondarybtn" href="https://wa.me/?text=${message}" target="_blank" rel="noopener">WhatsApp</a><a class="secondarybtn" href="https://t.me/share/url?url=${encodeURIComponent(SHAMS_PUBLIC_URL)}&text=${encodeURIComponent(sw('shareText'))}" target="_blank" rel="noopener">Telegram</a></div><input id="shareLink" value="${SHAMS_PUBLIC_URL}" readonly aria-label="${sw('copy')}"><button class="secondarybtn wide" onclick="copyAppLink()">${sw('copy')}</button></section></div>`}
let specialSchool='hanafi',specialType='eid';
const specialText={
 eidH:[
 ['İmamla birlikdə 2 rükət bayram namazına niyyət edin. İftitah təkbirindən sonra Sübhanəkə oxunur.','İmamla iki rekât bayram namazına niyet edin. İftitah tekbirinden sonra Sübhaneke okunur.','Намерение на два ракаата с имамом. После вступительного такбира читается Субханака.','Intend two rakahs with the imam. After the opening takbir, recite Subhanaka.','انوِ ركعتين مع الإمام. بعد تكبيرة الإحرام يُقرأ دعاء الاستفتاح.'],
 ['Birinci rükətdə qiraətdən əvvəl 3 əlavə təkbir deyilir. İlk ikisində əllər yana buraxılır, üçüncüdə bağlanır.','İlk rekâtta kıraatten önce üç ek tekbir: ilk ikisinde eller yanlara bırakılır, üçüncüde bağlanır.','В первом ракаате до чтения — три дополнительных такбира. После первых двух руки опускаются, после третьего складываются.','In rakah one, say three extra takbirs before recitation. Release the hands after the first two; fold after the third.','في الركعة الأولى ثلاث تكبيرات زائدة قبل القراءة؛ تُرسل اليدان بعد الأوليين وتُضمّان بعد الثالثة.'],
 ['İmam Fatihə və surə oxuyur; sonra adi qaydada rüku və iki səcdə edilir.','İmam Fâtiha ve sûre okur; rükû ve iki secde yapılır.','Имам читает Аль-Фатиху и суру; затем руку и два суджуда.','The imam recites al-Fatihah and a surah; then perform ruku and two prostrations.','يقرأ الإمام الفاتحة وسورة ثم الركوع والسجدتين.'],
 ['İkinci rükətdə qiraətdən sonra 3 əlavə təkbir deyilir, əllər yana buraxılır. Növbəti təkbirlə rükuya gedilir.','İkinci rekâtta kıraatten sonra üç ek tekbirde eller yanlara bırakılır; sonraki tekbirle rükûya gidilir.','Во втором ракаате после чтения — три дополнительных такбира, опуская руки; со следующим такбиром совершается руку.','In rakah two, after recitation say three extra takbirs, releasing the hands; the next takbir leads into ruku.','في الثانية بعد القراءة ثلاث تكبيرات زائدة مع إرسال اليدين، ثم تكبيرة أخرى للركوع.'],
 ['İki səcdə, son oturuş və salamla tamamlayın. Sonra bayram xütbəsini dinləyin.','İki secde, son oturuş ve selamla tamamlayın. Sonra bayram hutbesini dinleyin.','Завершите двумя суджудами, последним сидением и салямом, затем слушайте праздничную хутбу.','Complete the prostrations, final sitting and salam; then listen to the Eid khutbah.','أتم السجدتين والتشهد والسلام ثم استمع إلى خطبة العيد.']
 ],
 eidJ:[
 ['2 rükət namaza niyyət edin. Birinci rükətdə Fatihə və bir surə oxuyun.','İki rekâta niyet edin; ilk rekâtta Fâtiha ve bir sûre okuyun.','Намерение на два ракаата. В первом читайте Аль-Фатиху и суру.','Intend two rakahs. Recite al-Fatihah and a surah in the first.','انوِ ركعتين، واقرأ الفاتحة وسورة في الأولى.'],
 ['Sistaninin cari 1498-ci hökmündə üstün variant: birinci rükətdə 5 təkbir, aralarında 4 qunut; sonra ayrıca təkbirlə rüku.','Sistani’nin güncel 1498. hükmündeki tercih edilen şekil: ilk rekâtta beş tekbir, aralarında dört kunut; sonra ayrı tekbirle rükû.','Предпочтительный вариант текущего правила Систани 1498: в первом ракаате пять такбиров и четыре кунута между ними; затем отдельный такбир для руку.','Preferred form in Sistani’s current ruling 1498: five takbirs with four qunuts between them in the first rakah, then a separate takbir for ruku.','الهيئة الأفضل في مسألة السيستاني الحالية ١٤٩٨: خمس تكبيرات بينها أربعة قنوتات في الأولى، ثم تكبيرة مستقلة للركوع.'],
 ['Rüku və iki səcdədən sonra qalxın. İkinci rükətdə Fatihə və bir surə oxuyun.','Rükû ve iki secdeden sonra kalkın; ikinci rekâtta Fâtiha ve bir sûre okuyun.','После руку и двух суджудов встаньте. Во втором ракаате прочитайте Аль-Фатиху и суру.','After ruku and two prostrations, rise and recite al-Fatihah and a surah in the second rakah.','بعد الركوع والسجدتين قم واقرأ الفاتحة وسورة في الثانية.'],
 ['İkinci rükətdə 4 təkbir, aralarında 3 qunut; sonra ayrıca təkbirlə rüku, iki səcdə, təşəhhüd və salam.','İkinci rekâtta dört tekbir, aralarında üç kunut; sonra ayrı tekbirle rükû, iki secde, teşehhüt ve selam.','Во втором — четыре такбира и три кунута между ними; затем отдельный такбир, руку, два суджуда, ташаххуд и салям.','In the second: four takbirs with three qunuts between, then a separate takbir, ruku, two prostrations, tashahhud and salam.','في الثانية أربع تكبيرات بينها ثلاثة قنوتات، ثم تكبيرة مستقلة فالركوع والسجدتان والتشهد والسلام.'],
 ['Vacib ehtiyat üzrə minimum variant hər rükətdə 3 təkbir və aralarında 2 qunut, sonra rüku təkbiridir. Mənbədəki variantları bir-birinə qarışdırmayın.','Vacip ihtiyata göre asgari şekil her rekâtta üç tekbir ve aralarında iki kunut, ardından rükû tekbiridir. Şekilleri karıştırmayın.','Минимум по обязательной предосторожности: в каждом ракаате три такбира и два кунута между ними, затем такбир для руку. Не смешивайте варианты.','The obligatory-precaution minimum is three takbirs with two qunuts between in each rakah, then the ruku takbir. Do not mix the variants.','الحد الأدنى على الأحوط وجوبًا ثلاث تكبيرات بينها قنوتان في كل ركعة، ثم تكبيرة الركوع. لا تخلط بين الهيئتين.']
 ],
 nightH:[
 ['Təravih Ramazan gecələrində işa namazından sonra, sübhədək qılınan nafilə namazdır. Bayram namazı deyil.','Teravih Ramazan gecelerinde yatsıdan sonra imsak vaktine kadar kılınan nafiledir; bayram namazı değildir.','Таравих — добровольный ночной намаз Рамадана после иша до фаджра; это не праздничный намаз.','Tarawih is a voluntary Ramadan night prayer after Isha and before Fajr, distinct from Eid prayer.','التراويح صلاة نافلة في ليالي رمضان بعد العشاء وقبل الفجر، وليست صلاة العيد.'],
 ['Hənəfi/Diyanet ənənəsində adətən 20 rükətdir; 2 rükətlik hissələrdə salam vermək olar. Hər hissə adi 2 rükətli nafilə ardıcıllığıdır.','Hanefi/Diyanet geleneğinde genellikle 20 rekâttır; ikişer rekâtta selam verilebilir. Her bölüm normal iki rekât nafiledir.','В ханафитской традиции Diyanet обычно 20 ракаатов; можно завершать салямом каждые два ракаата, как обычную добровольную молитву.','The Hanafi/Diyanet tradition commonly observes 20 rakahs, which may be prayed in two-rakah units with salam. Each unit follows an ordinary voluntary prayer.','في التقليد الحنفي لدى ديانت تُصلّى عادة عشرين ركعة، ويجوز التسليم كل ركعتين كصلاة نافلة عادية.'],
 ['Camaatla qılarkən imamı izləyin. Vitr ayrıca namazdır; digər məktəblərin rükət sayı və tətbiqi fərqlənə bilər.','Cemaatte imama uyun. Vitir ayrı namazdır; diğer mezheplerin rekât sayısı ve uygulaması farklı olabilir.','В джамаате следуйте имаму. Витр — отдельный намаз; у других школ число ракаатов может отличаться.','Follow the imam in congregation. Witr is separate; other traditions may use different counts and practices.','اتبع الإمام في الجماعة. الوتر صلاة مستقلة، وقد تختلف الأعداد والكيفية في المذاهب الأخرى.']
 ],
 nightJ:[
 ['Cəfəri qaydasında Ramazan nafilələri fərdi qılınır; təravih camaatı kimi təşkil edilmir.','Caferi uygulamasında Ramazan nafileleri bireyseldir; teravih cemaati şeklinde düzenlenmez.','В джафаритской традиции рамаданские нафиля совершаются индивидуально, не как коллективный таравих.','In the Jafari tradition, Ramadan voluntary prayers are individual, not congregational tarawih.','في المذهب الجعفري تُصلّى نوافل رمضان فرادى ولا تُقام جماعة تراويح.'],
 ['Nafilələri adətən 2 rükətlik hissələrdə qılın: qiraət, rüku, iki səcdə; ikinci rükət, təşəhhüd və salam. Dəqiq niyyət və say üçün təqlid etdiyiniz mənbəyə baxın.','Nafileler genellikle ikişer rekâttır: kıraat, rükû, iki secde; ikinci rekât, teşehhüt ve selam. Niyet ve sayı için merciinize başvurun.','Обычно нафиля читаются по два ракаата: чтение, руку, два суджуда; второй ракаат, ташаххуд и салям. Намерение и число уточняйте у своего марджа.','Voluntary prayers are generally offered in two-rakah units: recitation, ruku, two prostrations; second rakah, tashahhud and salam. Consult your marja for intention and counts.','تُصلّى النوافل عادة ركعتين: قراءة وركوع وسجدتان، ثم الثانية والتشهد والسلام. راجع مرجعك للنية والعدد.']
 ]};
function specialPrayersPage(){const j=specialSchool==='jafari',night=specialType==='night',index=['az','tr','ru','en','ar'].indexOf(lang()),rows=specialText[night?(j?'nightJ':'nightH'):(j?'eidJ':'eidH')],source=j?'https://www.sistani.org/english/book/48/'+(night?'2268/':'2275/'):(night?'https://kurul.diyanet.gov.tr/tr/fetva/teravih-namazinin-hukmu-ve-mahiyeti-nedir/0193c42d-5db2-75bd-16ba-e3e9895d4b86':'https://igdir.diyanet.gov.tr/sayfalar/contentdetail.aspx?ContentId=1850&MenuCategory=Kurumsal');return `<div data-localized="true">${head(sw('special'),'')}<div class="tabs"><button onclick="specialType='eid';render()" class="${!night?'active':''}" aria-pressed="${!night}">${sw('eid')}</button><button onclick="specialType='night';render()" class="${night?'active':''}" aria-pressed="${night}">${sw('ramadan')}</button></div><div class="tabs" aria-label="${sw('school')}"><button onclick="specialSchool='hanafi';render()" class="${!j?'active':''}" aria-pressed="${!j}">${tr('Hənəfi')}</button><button onclick="specialSchool='jafari';render()" class="${j?'active':''}" aria-pressed="${j}">${tr('Cəfəri')}</button></div><section class="card"><h2>${sw(night?'ramadan':'eid')}</h2>${night?'':`<p class="notice">${sw('eidNote')}</p>`}<ol class="special-steps">${rows.map((r,i)=>`<li><span>${i+1}</span><p>${r[index]||r[0]}</p></li>`).join('')}</ol><p class="notice">${sw('reminder')}</p><a class="source-link" href="${source}" target="_blank" rel="noopener">${sw('source')} · ${j?'Sistani':'Diyanet'} ↗</a></section></div>`}
function initializeSocialWorship(){for(const [r,i,t]of [['share','↗',sw('share')],['special','☾',sw('special')]])if(!extra.some(x=>x[0]===r))extra.push([r,i,t]);window.addEventListener('hashchange',()=>{document.querySelector('#azanAudio')?.pause()});}

const socialRamadanPage=cosmicRamadan;cosmicRamadan=function(){return socialRamadanPage()+specialPrayerLink()};

swWords.apk=['Android APK yüklə','Android APK indir','Скачать Android APK','Download Android APK','تنزيل Android APK'];
function apkDownloadCard(){return '<section class="card" data-localized="true"><h3>SHAMS · Android</h3><a class="goldbtn wide" href="https://mubaristi-create.github.io/basira/downloads/SHAMS-1.3.0.apk">'+sw('apk')+' ↓</a><p class="notice">Android 8.0+ · SHAMS 1.3.0</p></section>'}
const socialMobilePage=localizedMobilePage;localizedMobilePage=function(){if(window.ShamsAndroid)return head('SHAMS · Android','')+apkDownloadCard();const html=socialMobilePage(),at=html.indexOf('<section');return html.slice(0,at)+apkDownloadCard()+html.slice(at)};
